"""Binary Tree Inorder Traversal — explicit stack, left-node-right.

Time: O(n)   Space: O(h)
"""
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def inorderTraversal(self, root) -> List[int]:
        out, stack, node = [], [], root
        while node or stack:
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            out.append(node.val)
            node = node.right
        return out
